#include <iostream>
#include <memory>
#include <stdexcept>
#include <string>

class Notification {
public:
    virtual void send() const = 0;
    virtual ~Notification() = default;
};

class EmailNotification : public Notification {
    std::string message;
public:
    explicit EmailNotification(std::string message) : message(std::move(message)) {}
    void send() const override { std::cout << "Sending email: " << message << std::endl; }
};

class SmsNotification : public Notification {
    std::string message;
public:
    explicit SmsNotification(std::string message) : message(std::move(message)) {}
    void send() const override { std::cout << "Sending sms: " << message << std::endl; }
};

class PushNotification : public Notification {
    std::string message;
public:
    explicit PushNotification(std::string message) : message(std::move(message)) {}
    void send() const override { std::cout << "Sending push: " << message << std::endl; }
};

class NotificationFactory {
public:
    static std::unique_ptr<Notification> create(const std::string& type, const std::string& message) {
        if (type == "email") return std::make_unique<EmailNotification>(message);
        if (type == "sms") return std::make_unique<SmsNotification>(message);
        if (type == "push") return std::make_unique<PushNotification>(message);
        throw std::invalid_argument("Unknown notification type: " + type);
    }
};

void sendNotification(const std::string& type, const std::string& message) {
    auto notification = NotificationFactory::create(type, message);
    notification->send();
}

void sendBillingAlert(const std::string& type, const std::string& message) {
    auto notification = NotificationFactory::create(type, message);
    notification->send();
}

int main() {
    sendNotification("email", "Your order has shipped");
    sendNotification("sms", "Your order has shipped");
    sendNotification("push", "Your order has shipped");

    sendBillingAlert("email", "Your invoice is ready");
    sendBillingAlert("sms", "Your invoice is ready");
    sendBillingAlert("push", "Your invoice is ready");
    return 0;
}
